const Login = () => <h1>Login</h1>


const Router = () => (
  <BrowserRouter>
    <Switch>
      <Route exact path="/" component={Home} />
      <Route component={NotFound} />
      <Route

      />
    </Switch>
  </BrowserRouter>
);

export default Router;
